        return { t: 'token', type: node.type, syntax: node.syntax ? node.syntax.type + ':' + node.syntax.name : null, nodeType: node.node && node.node.type, nodeValue: node.node && node.node.value, keys: Object.keys(node) };
    }
    return { t: 'branch', syntax: node.syntax ? node.syntax.type + ':' + node.syntax.name : null, match: node.match.map(c => summarize(c, depth+1)) };
}
console.log(JSON.stringify(summarize(res.matched), null, 2));
EOF
