                'font-weight': 'normal',
                'font-stretch': 'normal',
                'font-size': '16px',
                'line-height': '1.5',
                'font-family': 'Arial'
            }),
            'normal normal normal normal 16px/1.5 Arial'
        );
    });

    it('compresses background layers', () => {
        const longhands = {
